export interface ReferenceIndexSection {
  title: string;
  links: readonly { path: string; title: string }[];
}

/** Generate a Markdown index from normalized reference sections. */
export function generateReferenceIndex(
  title: string,
  sections: readonly ReferenceIndexSection[]
): string {
  const lines = [
    '<!-- Generated by src/bin/ai-sync.ts. Do not edit manually. -->',
    '',
    `# ${title} index`,
    '',
    'Load only relevant entries.',
  ];

  for (const section of sections) {
    lines.push('', `## ${section.title}`, '');
    for (const link of section.links) {
      lines.push(`- [${link.title}](${link.path})`);
    }
  }

  return `${lines.join('\n')}\n`;
}
